// Runtime support for statically recompiled PSP code (generated by tools/recomp.py).
// Every helper mirrors the matching interpreter function in Core/MIPS/Interpreter.cpp, so the
// compiled code computes bit-identical results. Guest memory is accessed without checks
// through Memory::base, like the JITs' fast path.

#pragma once

#include <cmath>
#include <cstring>

#include "Common/CommonTypes.h"
#include "Common/BitScan.h"
#include "Common/BitSet.h"
#include "Common/Math/math_util.h"
#include "Core/Core.h"
#include "Core/MemMap.h"
#include "Core/MIPS/MIPS.h"
#include "Core/Recomp/Recomp.h"

#define R(i) (m->r[i])
#define F(i) (m->f[i])
#define FI(i) (m->fi[i])
#define FS(i) (m->fs[i])
#define RC_RUNNING (coreState == CORE_RUNNING_CPU)

#define LB(a) ((u32)(s32) * (s8 *)(mem + (u32)(a)))
#define LBU(a) ((u32) * (u8 *)(mem + (u32)(a)))
#define LH(a) ((u32)(s32) * (s16 *)(mem + (u32)(a)))
#define LHU(a) ((u32) * (u16 *)(mem + (u32)(a)))
#define LW(a) (*(u32 *)(mem + (u32)(a)))
#define SB(a, v) (*(u8 *)(mem + (u32)(a)) = (u8)(v))
#define SH(a, v) (*(u16 *)(mem + (u32)(a)) = (u16)(v))
#define SW(a, v) (*(u32 *)(mem + (u32)(a)) = (u32)(v))

// Leave if a call didn't come back where expected (thread switch, interrupt, timeslice end).
#define RC_CHECK_RET(ret) \
	if (m->pc != (u32)(ret) || !RC_RUNNING) \
		return;

// A replacement function (ReplaceTables) is run by the interpreter: refuse the entry.
#define RC_HOOK_CHECK(addr) \
	if (*Memory::GetBlockShadowEntry(addr) != 0) { \
		m->pc = (addr); \
		return; \
	}

static inline u32 RC_lwl(u8 *mem, u32 addr, u32 reg) {
	const u32 word = LW(addr & 0xfffffffc);
	const u32 shift = (addr & 3) * 8;
	return (reg & (0x00ffffff >> shift)) | (word << (24 - shift));
}

static inline u32 RC_lwr(u8 *mem, u32 addr, u32 reg) {
	const u32 word = LW(addr & 0xfffffffc);
	const u32 shift = (addr & 3) * 8;
	return (reg & (0xffffff00 << (24 - shift))) | (word >> shift);
}

static inline void RC_swl(u8 *mem, u32 addr, u32 reg) {
	const u32 shift = (addr & 3) * 8;
	const u32 word = LW(addr & 0xfffffffc);
	SW(addr & 0xfffffffc, (reg >> (24 - shift)) | (word & (0xffffff00 << shift)));
}

static inline void RC_swr(u8 *mem, u32 addr, u32 reg) {
	const u32 shift = (addr & 3) << 3;
	const u32 word = LW(addr & 0xfffffffc);
	SW(addr & 0xfffffffc, (reg << shift) | (word & (0x00ffffff >> (24 - shift))));
}

static inline void RC_div(MIPSState *m, u32 rs, u32 rt) {
	const s32 a = (s32)rs;
	const s32 b = (s32)rt;
	if (a == (s32)0x80000000 && b == -1) {
		m->lo = 0x80000000;
		m->hi = 0;
	} else if (b != 0) {
		m->lo = (u32)(a / b);
		m->hi = (u32)(a % b);
	} else {
		m->lo = a < 0 ? 1 : -1;
		m->hi = a;
	}
}

static inline void RC_divu(MIPSState *m, u32 a, u32 b) {
	if (b != 0) {
		m->lo = a / b;
		m->hi = a % b;
	} else {
		m->lo = a <= 0xFFFF ? 0xFFFF : -1;
		m->hi = a;
	}
}

static inline void RC_mult(MIPSState *m, u32 a, u32 b) {
	const u64 r = (u64)((s64)(s32)a * (s64)(s32)b);
	m->lo = (u32)r;
	m->hi = (u32)(r >> 32);
}

static inline void RC_multu(MIPSState *m, u32 a, u32 b) {
	const u64 r = (u64)a * (u64)b;
	m->lo = (u32)r;
	m->hi = (u32)(r >> 32);
}

static inline void RC_madd(MIPSState *m, u32 a, u32 b, bool sub, bool isSigned) {
	const u64 orig = (u64)m->lo | ((u64)m->hi << 32);
	u64 r;
	if (isSigned) {
		const s64 prod = (s64)(s32)a * (s64)(s32)b;
		r = (u64)(sub ? (s64)orig - prod : (s64)orig + prod);
	} else {
		const u64 prod = (u64)a * (u64)b;
		r = sub ? orig - prod : orig + prod;
	}
	m->lo = (u32)r;
	m->hi = (u32)(r >> 32);
}

static inline u32 RC_ins(u32 rt, u32 rs, int pos, int sizeField) {
	const u32 mask = 0xFFFFFFFFUL >> (31 - sizeField);
	const u32 sourcemask = mask >> pos;
	const u32 destmask = sourcemask << pos;
	return (rt & ~destmask) | ((rs & sourcemask) << pos);
}

static inline u32 RC_cfc1(MIPSState *m, int fs) {
	if (fs == 31) {
		m->fcr31 = (m->fcr31 & ~(1 << 23)) | ((m->fpcond & 1) << 23);
		return m->fcr31;
	}
	if (fs == 0)
		return MIPSState::FCR0_VALUE;
	return 0;
}

static inline void RC_ctc1(MIPSState *m, int fs, u32 value) {
	if (fs == 31) {
		m->fcr31 = value & 0x0181FFFF;
		m->fpcond = (value >> 23) & 1;
		ApplyHostRoundingMode(m);
	}
}

static inline void RC_mul_s(MIPSState *m, int fd, int fs, int ft) {
	if ((my_isinf(F(fs)) && F(ft) == 0.0f) || (my_isinf(F(ft)) && F(fs) == 0.0f)) {
		FI(fd) = 0x7fc00000;
	} else {
		F(fd) = F(fs) * F(ft);
	}
}

static inline void RC_div_s(MIPSState *m, int fd, int fs, int ft) {
	m->fcr31 &= ~FCR31_CAUSE_DIV_BY_ZERO;
	if (F(ft) == 0.0f && F(fs) != 0.0f && !my_isnanorinf(F(fs))) {
		m->fcr31 |= FCR31_CAUSE_DIV_BY_ZERO;
		if ((m->fcr31 & FCR31_ENABLE_DIV_BY_ZERO) == 0)
			m->fcr31 |= FCR31_FLAG_DIV_BY_ZERO;
	}
	F(fd) = F(fs) / F(ft);
}

static inline void RC_sqrt_s(MIPSState *m, int fd, int fs) {
	F(fd) = sqrtf(F(fs));
	if (F(fs) < 0.0f)
		FS(fd) = 0x7FC00000;
}

// mode: 0 round, 1 trunc, 2 ceil, 3 floor.
static inline s32 RC_f2i(float f, int mode) {
	switch (mode) {
	case 0: return SaturatedFloatToInt(round_ieee_754(f));
	case 1: return SaturatedFloatToInt(truncf(f));
	case 2: return SaturatedFloatToInt(ceilf(f));
	default: return SaturatedFloatToInt(floorf(f));
	}
}

static inline bool RC_fcmp(int cond, float a, float b) {
	switch (cond & 7) {
	case 0: return false;
	case 1: return my_isnan(a) || my_isnan(b);
	case 2: return !my_isnan(a) && !my_isnan(b) && (a == b);
	case 3: return (a == b) || my_isnan(a) || my_isnan(b);
	case 4: return a < b;
	case 5: return (a < b) || my_isnan(a) || my_isnan(b);
	case 6: return a <= b;
	default: return (a <= b) || my_isnan(a) || my_isnan(b);
	}
}

// jalr / jr to a computed address.
static inline void RC_CallIndirect(MIPSState *m, u32 target) {
	RecompFunc f = Recomp_Lookup(target);
	if (f) {
		m->pc = target;
		f(m);
	} else if (!Recomp_TryStub(m, target)) {
		m->pc = target;
	}
}
